// RESPONSIBILITY: Defines runtime validation schemas for blacklist_management; it does not determine server-owned business rules without a verified contract.
// DATA FLOW: API/form boundary → Zod schema → validated typed data or field-level errors → owning hook/view (admin_blacklist/blacklist_management/schemas/AdminMembersBlacklistManagementSchemas.ts)

import { z } from 'zod';
// Generated by ts-to-zod


export const statusSchema = z.union([z.literal("idle"), z.literal("loading"), z.literal("success"), z.literal("error")]);

export const blacklistScopeSchema = z.union([z.literal("global"), z.literal("specific")]);

export const blacklistedMemberSchema = z.object({
    id: z.string(),
    memberId: z.string(),
    memberName: z.string(),
    memberPhone: z.string(),
    memberEmail: z.string(),
    reason: z.string(),
    blacklistedBy: z.string(),
    blacklistedAt: z.string(),
    scope: blacklistScopeSchema,
    assignedGyms: z.array(z.string()),
    assignedGymNames: z.array(z.string()),
    isActive: z.boolean(),
    history: z.array(z.object({
        action: z.string(),
        actor: z.string(),
        timestamp: z.string(),
        note: z.string()
    })).optional()
}).superRefine((value, context) => {
  const includesAllGyms = value.assignedGyms.includes('all');
  if (value.scope === 'specific' && (includesAllGyms || value.assignedGyms.length === 0)) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['assignedGyms'], message: 'Specific-scope records must identify one or more gyms, not all gyms.' });
  }
  if (value.scope === 'global' && (value.assignedGyms.length !== 1 || !includesAllGyms)) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['assignedGyms'], message: 'Global-scope records must use the single all-gyms sentinel.' });
  }
});

export const blacklistFormValuesSchema = z.object({
    memberId: z.string(),
    memberName: z.string(),
    memberPhone: z.string(),
    memberEmail: z.string(),
    reason: z.string(),
    scope: blacklistScopeSchema,
    assignedGyms: z.array(z.string())
});

export const blacklistKpiDataSchema = z.object({
    totalBlacklisted: z.number(),
    globalBans: z.number(),
    gymSpecificBans: z.number(),
    addedThisMonth: z.number()
});

export const blacklistFormSchema = z.object({
  memberId: z.string().trim().min(1, '__i18n:blacklist.validation.memberIdRequired'),
  memberName: z.string().trim().min(2, '__i18n:blacklist.validation.nameRequired'),
  memberPhone: z.string().regex(/^\d{10}$/, '__i18n:blacklist.validation.phoneInvalid'),
  memberEmail: z.string().trim().email('__i18n:blacklist.validation.emailInvalid'),
  reason: z.string().trim().min(10, '__i18n:blacklist.validation.reasonMin'),
  scope: z.enum(['global', 'specific']),
  assignedGyms: z.array(z.string()).min(1, '__i18n:blacklist.validation.gymRequired'),
}).superRefine((value, context) => {
  const includesAllGyms = value.assignedGyms.includes('all');
  if (value.scope === 'specific' && (includesAllGyms || value.assignedGyms.length === 0)) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['assignedGyms'], message: '__i18n:blacklist.validation.specificGymsOnly' });
  }
  if (value.scope === 'global' && (value.assignedGyms.length !== 1 || !includesAllGyms)) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['assignedGyms'], message: '__i18n:blacklist.validation.globalScopeAllGyms' });
  }
});

